-- ════════════════════════════════════════════════════════════════════
--  0030 · seed «Dove ci innestiamo» (Intesa Sanpaolo) into the Console registry
--  Registers the experience (card in Super Admin, FK for restricted_docs).
--  Starts as DRAFT and OFF the showcase (show_in_showcase=false): switching
--  it on makes it public on a page without login — a human decision.
--  Generated by `pnpm new:experience` on 2026-10-23. Idempotent.
--  Apply once (human action): supabase db query --linked
-- ════════════════════════════════════════════════════════════════════

insert into public.experiences (slug, name, client, description, base_url, status, show_in_showcase, type)
values (
  'intesa-innesto',
  'Dove ci innestiamo',
  'Intesa Sanpaolo',
  'Come si collega a quello che abbiamo? Blueprint per la Divisione Banca dei Territori: dove ci innestiamo sull''impianto che hanno già — la scelta all''ultimo metro e la storia del cliente ricomposta. Prepara l''incontro del 5 novembre 2026.',
  '/experience-design-factory/intesa-innesto/',
  'draft',
  false,
  'blueprint'
)
on conflict (slug) do update
   set name             = excluded.name,
       client           = excluded.client,
       description      = excluded.description,
       base_url         = excluded.base_url,
       status           = excluded.status,
       show_in_showcase = excluded.show_in_showcase,
       type             = excluded.type,
       updated_at       = now();
